import { isArray, isFunction } from "@arco-design/web-react/es/_util/is";
import { FC } from "react";
import { ReactChildren, ReactElement } from "react";

export const getReactChildrenByType = (
  type: string,
  children?: ReactChildren
) => {
  const c = isArray(children) ? children : children?.toArray?.(children);
  const list = (c
    ?.filter((child) => {
      const childType = (child as ReactElement)?.type;
      if (isFunction(childType)) {
        const name = (childType as FC).displayName || childType.name;
        return name === type;
      }
      return childType === type;
    })
    ?.filter(Boolean) || []) as ReactElement[];
  return list;
};
